from r5lib import c
T1 = {"dm_status":"known","dm_type_recorded":"type_1","glucose_lowering_therapy":["insulin"]}
T2 = {"dm_status":"known","dm_type_recorded":"type_2"}
M = lambda **k: {"sex":"male", **k}; F = lambda **k: {"sex":"female", **k}
c(M(age_years=30, dm_status="not_known", vomiting=True, abdominal_pain=True, urine_ketones="1plus"), est=False, label="A01 non-DM gastroenteritis urine 1+, no glucose")
c(M(age_years=30, dm_status="not_known", vomiting=True, urine_ketones="1plus", capillary_glucose=6.0), est=False, label="A01b same, glucose 6")
c(M(age_years=30, dm_status="not_known", vomiting=True, dehydration=True, urine_ketones="1plus", capillary_glucose=12.0), est=False, label="A01c non-DM, dehydrated malaria-like, glucose 12, urine 1+")
c(F(age_years=31, pregnant=True, gestation_weeks=12, bp_systolic=142, bp_diastolic=92), est=False, label="A02 pregnant 12w 142/92")
c(F(age_years=31, pregnant=True, gestation_weeks=12, bp_systolic=142, bp_diastolic=92, hypertension_known=True, **T2, glucose_lowering_therapy=["insulin"]), label="A02b 12w known T2 + chronic HTN 142/92")
c(F(age_years=28, pregnant=False, postpartum_weeks=2, bp_systolic=165, bp_diastolic=112, hypertensive_symptoms=True, prior_gdm=True), est=False, label="A02c 2w postpartum 165/112 headache")
c(M(age_years=55, **T2, glucose_lowering_therapy=["metformin"], bp_systolic=185, bp_diastolic=112, hypertensive_symptoms=True), label="A03 known DM 185/112 headache only")
c(M(age_years=55, dm_status="not_known", bp_systolic=185, bp_diastolic=112, hypertensive_symptoms=True), est=False, label="A03b non-DM 185/112 headache")
c(M(age_years=55, **T2, bp_systolic=230, bp_diastolic=130, chest_pain_or_stroke_symptoms=True), label="A04 230/130 + chest pain (double?)")
c(F(age_years=30, pregnant=True, gestation_weeks=34, bp_systolic=170, bp_diastolic=115, mental_status="drowsy"), est=False, label="A05 pregnant 170/115 drowsy")
c(M(age_years=15, **T1, deep_rapid_breathing=True), band="adolescent", label="A06 15y T1 Kussmaul, no glucose")
c(M(age_years=15, **T1, deep_rapid_breathing=True, capillary_glucose=22), band="adolescent", label="A06b 15y T1 Kussmaul, glucose 22")
c(M(age_years=15, **T1, deep_rapid_breathing=True, capillary_glucose=22), band="child", label="A06c same as child band")
c(M(age_years=50, **T2, glucose_lowering_therapy=["metformin","glimepiride"], capillary_glucose=3.5), label="A07 metformin+glimepiride 3.5")
c(M(age_years=70, **T2, egfr=22, hba1c=6.4), band="older_adult", label="A08 known DM eGFR22 HbA1c6.4 no med recorded")
c(M(age_years=70, egfr=22, hba1c=6.4), est=False, band="older_adult", label="A08b status blank, eGFR22 HbA1c6.4")
c(M(age_years=60, **T2, capillary_glucose=3.4), label="A09 known DM, med list BLANK, glucose 3.4")
c(M(age_years=60, **T2, capillary_glucose=3.5, mental_status="drowsy"), label="A10 known DM, med list blank, DROWSY, glucose 3.5")
c(M(age_years=60, **T2, glucose_lowering_therapy=["metformin"], capillary_glucose=3.5, mental_status="coma"), label="A10b metformin only, COMA, glucose 3.5")
c(M(age_years=50, glucose_lowering_therapy=["sglt2_inhibitor","metformin"], vomiting=True, abdominal_pain=True, capillary_glucose=9.0, urine_ketones="neg"), label="A11 SGLT2 vomit+pain glu9 urine NEG")
c(M(age_years=50, glucose_lowering_therapy=["sglt2_inhibitor","metformin"], vomiting=True, deep_rapid_breathing=True, capillary_glucose=9.0, urine_ketones="trace"), label="A12 SGLT2 Kussmaul glu9 trace, status blank")
c(M(age_years=50, glucose_lowering_therapy=["sglt2_inhibitor","metformin"], vomiting=True, deep_rapid_breathing=True, capillary_glucose=9.0, bohb=4.2), label="A12b SGLT2 Kussmaul glu9 bohb 4.2, status blank")
c(M(age_years=25, glucose_lowering_therapy=["insulin"], vomiting=True, capillary_glucose=8.0, urine_ketones="3plus"), label="A13 on insulin (status blank) vomit glu8 urine 3+")
c(M(age_years=10, **T1, vomiting=True, urine_ketones="neg"), band="child", label="A14 child T1 vomiting urine neg, NO glucose")
c(M(age_years=10, **T1, capillary_glucose=25, urine_ketones="neg"), band="child", label="A15 child T1 glucose 25 ketones neg, well")
c(M(age_years=10, **T1, vomiting=True, capillary_glucose=15), band="child", label="A15b child T1 vomiting glucose 15")
c(F(age_years=30, pregnant=True, gestation_weeks=26, capillary_glucose=6.3, capillary_glucose_context="fasting"), est=False, label="A16 pregnant fasting meter 6.3")
c(M(age_years=40, **T2, capillary_glucose=12, urine_ketones="trace", bohb=0.3), label="A17 urine trace but bohb 0.3")
c(M(age_years=40, **T2, capillary_glucose=20, urine_ketones="neg", bohb=3.5), label="A18 urine neg, bohb 3.5, glu 20")
c(M(age_years=40, **T2, capillary_glucose=20, urine_ketones="1plus", deep_rapid_breathing=True), label="A19 glu 20, 1+, Kussmaul")
c(M(age_years=40, **T2, glucose_lowering_therapy=["insulin"], capillary_glucose=12, dehydration=True), label="A20 insulin glu12 dehydrated")
